812: function updateCreatureTag() {
813:   const creature = creatures.selected;
814:   if (!creature || !els.creatureTag) return;
815:   const dims = creature.dimensions;
816:   tagWorld.set(
817:     creature.position.x,
818:     creature.position.y + (dims.bodyY + dims.neckLen * 0.55 + 0.32) * creature.sizeScale,
819:     creature.position.z,
820:   );
821:   tagWorld.project(world.camera);
822:   if (tagWorld.z > 1 || tagWorld.z < -1) {
823:     els.creatureTag.style.opacity = "0";
824:     return;
825:   }
826:   const x = (tagWorld.x * 0.5 + 0.5) * window.innerWidth;
