46: function gaussian(rng) {
47:   const u = Math.max(1e-9, rng());
48:   const v = Math.max(1e-9, rng());
49:   return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
50: }
