export const GENE_KEYS = [
  "bodySize",
  "neck",
  "legs",
  "tail",
  "armor",
  "speed",
  "fat",
  "crest",
  "hue",
  "pattern",
];

export const GENE_META = {
  bodySize: { label: "Body mass", code: "BMP-4", unit: "kg" },
  neck: { label: "Neck reach", code: "HOX-7", unit: "m" },
  legs: { label: "Limb length", code: "SHH-2", unit: "m" },
  tail: { label: "Caudal length", code: "WNT-3", unit: "m" },
  armor: { label: "Dermal armor", code: "EDAR", unit: "%" },
  speed: { label: "Sprint capacity", code: "MYH-1", unit: "m/s" },
  fat: { label: "Adipose layer", code: "FTO-2", unit: "cm" },
  crest: { label: "Display crest", code: "DLX-5", unit: "%" },
  hue: { label: "Pigment hue", code: "TYR-1", unit: "°" },
  pattern: { label: "Pattern density", code: "KIT-3", unit: "%" },
};

export const TRAIT_ROWS = ["bodySize", "neck", "legs", "armor", "speed", "fat", "tail"];

export const CLIMATE = ["Frigid", "Temperate", "Arid"];
export const FORAGE = ["Sparse", "Balanced", "Lush"];
export const PREDATION = ["Absent", "Stalking", "Rampant"];

const clamp01 = (v) => Math.max(0, Math.min(1, v));

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gaussian(rng) {
  const u = Math.max(1e-9, rng());
  const v = Math.max(1e-9, rng());
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

export function randomGenome(rng = Math.random, center = 0.5, spread = 0.13) {
  const genome = {};
  for (const key of GENE_KEYS) {
    let lo = center - spread;
    let hi = center + spread;
    if (key === "hue") {
      lo = 0.28;
      hi = 0.74;
    }
    if (key === "pattern") {
      lo = 0.25;
      hi = 0.8;
    }
    genome[key] = Math.min(1, Math.max(0, lo + rng() * (hi - lo)));
  }
  return genome;
}

export function crossover(a, b, rng = Math.random) {
  const child = {};
  for (const key of GENE_KEYS) {
    const t = rng();
    const value = t < 0.44 ? a[key] : t < 0.88 ? b[key] : (a[key] + b[key]) / 2;
    child[key] = clamp01(value + gaussian(rng) * 0.018);
  }
  return child;
}

export function mutate(genome, rng = Math.random, rate = 0.2, power = 0.115) {
  const result = { ...genome };
  const changes = [];
  for (const key of GENE_KEYS) {
    if (rng() < rate) {
      const before = result[key];
      const step = gaussian(rng) * power;
      result[key] = clamp01(before + step);
      if (Math.abs(result[key] - before) > 0.004) {
        changes.push({
          gene: key,
          code: GENE_META[key].code,
          before,
          after: result[key],
          delta: result[key] - before,
        });
      }
    }
  }
  return { genome: result, changes };
}

