607:   chooseTarget(initial = false) {
608:     const angle = this.rng() * TAU;
609:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
610:     let x = this.home.x + Math.cos(angle) * dist;
611:     let z = this.home.z + Math.sin(angle) * dist;
612: 
613:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
614:       x = this.home.x - Math.cos(angle) * dist;
615:       z = this.home.z - Math.sin(angle) * dist;
616:     }
617:     const r = Math.hypot(x, z);
618:     if (r > 7.1) {
619:       x *= 7.1 / r;
620:       z *= 7.1 / r;
621:     }
622:     this.target.set(x, 0, z);
623:   }
