713:   dispose() {
714:     this.world.removeLifeObject(this.group);
715:     const disposed = new Set();
716:     this.group.traverse((obj) => {
717:       if (obj.geometry && !disposed.has(obj.geometry)) {
718:         disposed.add(obj.geometry);
719:         obj.geometry.dispose();
720:       }
721:       if (obj.material) {
722:         const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
723:         for (const mat of mats) {
724:           if (mat.map && !disposed.has(mat.map)) {
725:             disposed.add(mat.map);
726:             mat.map.dispose();
727:           }
728:           if (!disposed.has(mat)) {
729:             disposed.add(mat);
730:             mat.dispose();
731:           }
732:         }
733:       }
734:     });
735:     this.skinTexture?.dispose();
736:   }
737: }
