770:   select(index, updateFocus = true) {
771:     this.selectedIndex = Math.max(0, Math.min(this.creatures.length - 1, index));
772:     const creature = this.creatures[this.selectedIndex];
773:     if (!creature) return null;
774:     if (updateFocus) {
775:       this.world.setSelection(creature.position, creature.radius);
