783:     const position = old.position.clone();
784:     const wasSelected = this.selectedIndex === index;
785:     old.dispose();
786:     const creature = new Creature({
787:       genome: organism.genome,
788:       evaluation: organism.evaluation,
789:       world: this.world,
790:       rng: mulberry32(7103 + index * 193 + organism.id * 7),
791:       index,
792:       position,
793:     });
794:     organism.creature = creature;
795:     this.creatures[index] = creature;
796:     if (wasSelected) this.select(index);
797:     return creature;
