822:   hitTest(event) {
823:     const rect = this.world.renderer.domElement.getBoundingClientRect();
824:     this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
825:     this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
826:     this.raycaster.setFromCamera(this.pointer, this.world.camera);
827:     const hits = this.raycaster.intersectObjects(this.world.lifeGroup.children, true);
