548:     addLog(`Automatic selection engaged at ${state.speed}×.`, true);
549:     showToast("Evolution running", `A new generation every ${(6 / state.speed).toFixed(1)} seconds`, "▶", 2300);
550:   } else {
551:     addLog("Automatic selection paused. The basin is still alive.");
552:   }
553:   audio.click();
554: }
