410:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
411:     const g = this.genome;
412:     const upperLen = legLen * 0.55;
413:     const lowerLen = legLen * 0.48;
414:     const legRadius = 0.058 + g.bodySize * 0.032;
415:     const positions = [
416:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
417:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
418:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
419:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
420:     ];
421: 
422:     positions.forEach((entry, i) => {
423:       const root = new THREE.Group();
424:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
425:       this.model.add(root);
426: 
427:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
428:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
429:       root.add(shoulder);
430: 
431:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
432:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
433:       thigh.position.y = -upperLen * 0.36;
434:       thigh.castShadow = true;
435:       root.add(thigh);
436: 
437:       const upper = new THREE.Mesh(
438:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
439:         this.limbMat,
440:       );
441:       upper.position.y = -upperLen / 2;
442:       upper.castShadow = true;
443:       root.add(upper);
444: 
445:       const knee = new THREE.Group();
446:       knee.position.y = -upperLen;
447:       root.add(knee);
448: 
449:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
450:       kneeJoint.scale.setScalar(legRadius * 0.8);
451:       knee.add(kneeJoint);
452: 
453:       const lower = new THREE.Mesh(
454:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
455:         this.limbMat,
456:       );
457:       lower.position.y = -lowerLen / 2;
458:       lower.castShadow = true;
459:       knee.add(lower);
460: 
461:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
462:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
463:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
464:       foot.castShadow = true;
465:       knee.add(foot);
466: 
467:       for (let toe = -1; toe <= 1; toe += 1) {
468:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
469:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
470:         claw.rotation.x = Math.PI / 2.4;
471:         knee.add(claw);
472:       }
473: 
474:       this.legs.push({
475:         root,
476:         knee,
477:         phase: entry.phase,
478:         front: entry.front,
479:         upperLen,
480:         lowerLen,
481:         baseRot: entry.front ? 0.05 : -0.04,
482:       });
483:     });
484:   }
