607:   chooseTarget(initial = false) {
608:     const angle = this.rng() * TAU;
609:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
610:     let x = this.home.x + Math.cos(angle) * dist;
611:     let z = this.home.z + Math.sin(angle) * dist;
612: 
613:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
614:       x = this.home.x - Math.cos(angle) * dist;
615:       z = this.home.z - Math.sin(angle) * dist;
616:     }
617:     const r = Math.hypot(x, z);
618:     if (r > 7.1) {
619:       x *= 7.1 / r;
620:       z *= 7.1 / r;
621:     }
622:     this.target.set(x, 0, z);
623:   }
624: 
625:   update(dt) {
626:     const elapsed = this.world.time - this.spawnTime;
627:     const spawnT = clamp01(elapsed / 0.8);
628:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
629:     this.model.visible = spawnT > 0;
630:     if (spawnT < 1) {
631:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
632:       return;
633:     }
634:     this.model.rotation.z *= 0.9;
635: 
636:     const speedGene = 0.6 + this.genome.speed * 1.45;
637:     this.tempTarget.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
638:     const distance = this.tempTarget.length();
639:     if (distance < 0.22 || this.rng() < dt * 0.008) {
640:       this.chooseTarget();
641:     }
642: 
643:     const moving = distance > 0.35;
644:     this.moving = moving;
645:     if (moving) {
646:       this.tempTarget.normalize();
647:       const desired = Math.atan2(this.tempTarget.x, this.tempTarget.z);
648:       let diff = desired - this.heading;
649:       while (diff > Math.PI) diff -= TAU;
650:       while (diff < -Math.PI) diff += TAU;
651:       this.heading += diff * Math.min(1, dt * 2.4);
652:       this.group.rotation.y = this.heading;
653: 
654:       const step = Math.min(distance, dt * (0.16 + speedGene * 0.22));
655:       const nx = this.position.x + Math.sin(this.heading) * step;
656:       const nz = this.position.z + Math.cos(this.heading) * step;
657:       if (Math.hypot(nx - POND.x, nz - POND.z) > POND.radius + 0.5 && Math.hypot(nx, nz) < 7.35) {
658:         this.position.x = nx;
659:         this.position.z = nz;
660:       } else {
661:         this.chooseTarget();
662:       }
663:       this.walkPhase += dt * (3.9 + speedGene * 2.8);
664:     } else {
665:       this.walkPhase += dt * 1.1;
666:     }
667: 
668:     this.position.y = terrainHeight(this.position.x, this.position.z);
669:     this.group.position.x = this.position.x;
670:     this.group.position.z = this.position.z;
671:     this.group.position.y = this.position.y;
672: 
673:     const stride = moving ? 1 : 0.25;
674:     for (const leg of this.legs) {
675:       const swing = Math.sin(this.walkPhase + leg.phase) * 0.54 * stride;
676:       const lift = Math.max(0, Math.sin(this.walkPhase + leg.phase + Math.PI / 2)) * 0.28 * stride;
677:       leg.root.rotation.x = leg.baseRot + swing;
678:       leg.knee.rotation.x = -lift + (leg.front ? 0.18 : 0.32);
679:     }
680: 
681:     const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.026 : Math.sin(this.world.time * 1.4) * 0.006;
682:     this.model.position.y = bob;
683:     this.model.rotation.x = moving ? Math.sin(this.walkPhase) * 0.008 : 0;
684: 
685:     if (this.neckGroup) {
686:       this.neckGroup.rotation.z = Math.sin(this.walkPhase * 0.5 + 1.2) * 0.022;
687:       this.neckGroup.rotation.x = (0.62 + this.genome.neck * 0.2) + Math.sin(this.walkPhase * 0.5) * 0.027;
