626:   update(dt) {
627:     const elapsed = this.world.time - this.spawnTime;
628:     const spawnT = clamp01(elapsed / 0.8);
629:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
630:     this.model.visible = spawnT > 0;
631:     if (spawnT < 1) {
632:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
633:       return;
634:     }
635:     this.model.rotation.z *= 0.9;
636: 
637:     const speedGene = 0.6 + this.genome.speed * 1.45;
638:     this.tempTarget.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
639:     const distance = this.tempTarget.length();
640:     if (distance < 0.22 || this.rng() < dt * 0.008) {
641:       this.chooseTarget();
642:     }
643: 
644:     const moving = distance > 0.35;
645:     this.moving = moving;
646:     if (moving) {
647:       this.tempTarget.normalize();
648:       const desired = Math.atan2(this.tempTarget.x, this.tempTarget.z);
649:       let diff = desired - this.heading;
650:       while (diff > Math.PI) diff -= TAU;
651:       while (diff < -Math.PI) diff += TAU;
652:       this.heading += diff * Math.min(1, dt * 2.4);
653:       this.group.rotation.y = this.heading;
654: 
655:       const step = Math.min(distance, dt * (0.16 + speedGene * 0.22));
656:       const nx = this.position.x + Math.sin(this.heading) * step;
657:       const nz = this.position.z + Math.cos(this.heading) * step;
658:       if (Math.hypot(nx - POND.x, nz - POND.z) > POND.radius + 0.5 && Math.hypot(nx, nz) < 7.35) {
659:         this.position.x = nx;
660:         this.position.z = nz;
661:       } else {
662:         this.chooseTarget();
663:       }
664:       this.walkPhase += dt * (3.9 + speedGene * 2.8);
665:     } else {
666:       this.walkPhase += dt * 1.1;
667:     }
668: 
669:     this.position.y = terrainHeight(this.position.x, this.position.z);
670:     this.group.position.x = this.position.x;
671:     this.group.position.z = this.position.z;
672:     this.group.position.y = this.position.y;
673: 
674:     const stride = moving ? 1 : 0.25;
675:     for (const leg of this.legs) {
676:       const swing = Math.sin(this.walkPhase + leg.phase) * 0.54 * stride;
677:       const lift = Math.max(0, Math.sin(this.walkPhase + leg.phase + Math.PI / 2)) * 0.28 * stride;
678:       leg.root.rotation.x = leg.baseRot + swing;
679:       leg.knee.rotation.x = -lift + (leg.front ? 0.18 : 0.32);
680:     }
681: 
682:     const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.026 : Math.sin(this.world.time * 1.4) * 0.006;
683:     this.model.position.y = bob;
684:     this.model.rotation.x = moving ? Math.sin(this.walkPhase) * 0.008 : 0;
685: 
686:     if (this.neckGroup) {
687:       this.neckGroup.rotation.z = Math.sin(this.walkPhase * 0.5 + 1.2) * 0.022;
688:       this.neckGroup.rotation.x = (0.62 + this.genome.neck * 0.2) + Math.sin(this.walkPhase * 0.5) * 0.027;
689:     }
690:     if (this.headGroup) {
691:       this.headGroup.rotation.y = Math.sin(this.world.time * 0.7 + this.index) * 0.11;
692:       this.headGroup.rotation.z = Math.sin(this.walkPhase * 0.5) * 0.02;
693:     }
694:     for (let i = 1; i < this.tailJoints.length; i += 1) {
695:       const joint = this.tailJoints[i];
696:       joint.rotation.y = Math.sin(this.world.time * 1.7 + i * 0.8 + this.index) * (0.06 + i * 0.012);
697:       joint.rotation.x = 0.035 + Math.sin(this.world.time * 1.1 + i) * 0.012;
698:     }
699:     for (const crest of this.crestMeshes) {
700:       crest.rotation.y = Math.PI / 2 + Math.sin(this.world.time * 2.1 + this.index) * 0.035;
701:     }
702: 
703:     const blink = (this.world.time + this.blinkPhase) % 4.6;
704:     const closed = blink > 4.42 ? 0.12 : 1;
705:     for (const eye of this.eyes) {
706:       eye.scale.y = eye.userData.baseScaleY * closed;
707:     }
708:   }
709: 
710:   setVisible(value) {
711:     this.group.visible = value;
712:   }
713: 
714:   dispose() {
715:     this.world.removeLifeObject(this.group);
716:     const disposed = new Set();
717:     this.group.traverse((obj) => {
718:       if (obj.geometry && !disposed.has(obj.geometry)) {
719:         disposed.add(obj.geometry);
720:         obj.geometry.dispose();
721:       }
722:       if (obj.material) {
723:         const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
724:         for (const mat of mats) {
725:           if (mat.map && !disposed.has(mat.map)) {
726:             disposed.add(mat.map);
727:             mat.map.dispose();
728:           }
729:           if (!disposed.has(mat)) {
730:             disposed.add(mat);
731:             mat.dispose();
732:           }
733:         }
734:       }
735:     });
736:     this.skinTexture?.dispose();
737:   }
738: }
