750:   spawnPopulation(population, positions) {
751:     for (const creature of this.creatures) {
752:       creature.dispose();
753:     }
754:     this.creatures = [];
755:     population.forEach((organism, index) => {
756:       const creature = new Creature({
757:         genome: organism.genome,
758:         evaluation: organism.evaluation,
759:         world: this.world,
760:         rng: mulberry32(3001 + index * 137 + organism.id * 13),
761:         index,
762:         position: positions[index],
763:       });
764:       organism.creature = creature;
765:       this.creatures.push(creature);
766:     });
767:     this.selectedIndex = Math.min(this.selectedIndex, this.creatures.length - 1);
768:     this.select(this.selectedIndex, true);
769:   }
770: 
771:   select(index, updateFocus = true) {
772:     this.selectedIndex = Math.max(0, Math.min(this.creatures.length - 1, index));
773:     const creature = this.creatures[this.selectedIndex];
774:     if (!creature) return null;
775:     if (updateFocus) {
776:       this.world.setSelection(creature.position, creature.radius);
777:     }
778:     return creature;
