94: export class Creature {
95:   constructor({ genome, evaluation, world, rng, index, position, stage = "organism" }) {
96:     this.genome = genome;
97:     this.evaluation = evaluation;
98:     this.stage = stage;
99:     this.world = world;
100:     this.rng = rng;
101:     this.index = index;
102:     this.nameData = nameCreature(genome);
103:     this.spawnTime = world.time;
104:     this.group = new THREE.Group();
105:     this.group.userData.creature = this;
106:     this.group.userData.creatureId = index;
107:     this.model = new THREE.Group();
108:     this.group.add(this.model);
109:     this.world.addLifeObject(this.group);
110: 
111:     this.position = new THREE.Vector3(position.x, terrainHeight(position.x, position.z), position.z);
112:     this.home = this.position.clone();
113:     this.group.position.copy(this.position);
114:     this.heading = rng() * TAU;
115:     this.group.rotation.y = this.heading;
116:     this.target = this.position.clone();
117:     this.walkPhase = rng() * TAU;
118:     this.blinkPhase = rng() * 8;
119:     this.moving = false;
120:     this.selected = false;
121:     this.dimensions = {};
122:     this.movementSpeed = 0.8;
123:     this.legs = [];
124:     this.tailJoints = [];
125:     this.eyes = [];
126:     this.crestMeshes = [];
127:     this.tempTarget = new THREE.Vector3();
128: 
129:     this.build();
130:     this.chooseTarget(true);
131:     if (index === 0) {
132:       this.heading = Math.atan2(
133:         world.camera.position.x - this.position.x,
134:         world.camera.position.z - this.position.z,
135:       );
136:       this.group.rotation.y = this.heading;
137:       this.target.set(
138:         this.position.x + Math.sin(this.heading) * 1.2,
139:         this.position.y,
140:         this.position.z + Math.cos(this.heading) * 1.2,
141:       );
142:     }
143:   }
144: 
145:   get radius() {
146:     return (0.58 + this.genome.bodySize * 0.42) * (0.82 + this.genome.bodySize * 0.5);
147:   }
148: 
149:   build() {
150:     const g = this.genome;
151:     const rng = this.rng;
152:     const sizeScale = 0.82 + g.bodySize * 0.55;
153:     this.sizeScale = sizeScale;
154:     this.model.scale.setScalar(0.01);
155:     this.spawnTime = this.world.time;
156: 
157:     const skin = makeSkinTexture(g, this.index + 3);
158:     this.skinTexture = skin.texture;
159:     const hue = skin.hue;
160:     const baseColor = new THREE.Color().setHSL(hue / 360, skin.saturation / 100, skin.lightness / 100, THREE.SRGBColorSpace);
161:     const accentColor = new THREE.Color().setHSL(((hue + 48) % 360) / 360, 0.46, 0.36, THREE.SRGBColorSpace);
162:     const bellyColor = new THREE.Color().setHSL(((hue + 14) % 360) / 360, 0.22, 0.57, THREE.SRGBColorSpace);
163:     const limbColor = new THREE.Color().setHSL(((hue - 2) % 360) / 360, 0.3, 0.28, THREE.SRGBColorSpace);
164:     this.themeColor = baseColor;
165:     this.accentColor = accentColor;
166: 
167:     this.bodyMat = new THREE.MeshStandardMaterial({
168:       map: skin.texture,
169:       bumpMap: skin.texture,
170:       bumpScale: 0.012,
171:       roughness: 0.76,
172:       metalness: 0.015,
173:       color: 0xffffff,
174:     });
175:     this.limbMat = new THREE.MeshStandardMaterial({
176:       color: limbColor,
177:       roughness: 0.83,
178:       metalness: 0.01,
179:     });
180:     this.bellyMat = new THREE.MeshStandardMaterial({ color: bellyColor, roughness: 0.86 });
181:     this.boneMat = new THREE.MeshStandardMaterial({ color: 0xaaa48d, roughness: 0.7, metalness: 0.03 });
182:     this.darkBoneMat = new THREE.MeshStandardMaterial({ color: 0x6e6858, roughness: 0.84 });
183:     this.eyeMat = new THREE.MeshStandardMaterial({ color: 0x090d0a, roughness: 0.17, metalness: 0.12 });
184:     this.glintMat = new THREE.MeshBasicMaterial({ color: 0xd9ffed });
185:     this.crestMat = new THREE.MeshStandardMaterial({
186:       color: accentColor,
187:       emissive: accentColor,
188:       emissiveIntensity: 0.08,
189:       roughness: 0.78,
190:       transparent: true,
191:       opacity: 0.82,
192:       side: THREE.DoubleSide,
193:     });
194:     this.accentMat = new THREE.MeshStandardMaterial({
195:       color: accentColor,
196:       emissive: accentColor,
197:       emissiveIntensity: 0.16,
198:       roughness: 0.6,
199:       transparent: true,
200:       opacity: 0.8,
201:       side: THREE.DoubleSide,
202:     });
203:     this.spotMat = new THREE.MeshStandardMaterial({
204:       color: accentColor,
205:       emissive: accentColor,
206:       emissiveIntensity: 0.3,
207:       roughness: 0.45,
208:       transparent: true,
209:       opacity: 0.6,
210:     });
211: 
212:     if (this.stage === "cellular") {
213:       this.buildCell();
214:       return;
215:     }
216: 
217:     // Proportions: raw genes become an actual biological body plan.
218:     const bodyLen = 0.9;
219:     const bodyW = 0.29 + g.fat * 0.1;
220:     const bodyH = 0.32 + g.fat * 0.11;
221:     const legLen = 0.53 + g.legs * 0.8;
222:     const neckLen = 0.15 + g.neck * 0.9;
223:     const tailLen = 0.24 + g.tail * 1.02;
224:     const bodyY = legLen + bodyH * 0.26 + 0.03;
225:     this.dimensions = { bodyLen, bodyW, bodyH, legLen, neckLen, tailLen, bodyY };
226:     this.bodyY = bodyY;
227: 
228:     const sphereGeo = new THREE.SphereGeometry(1, 24, 18);
229:     this.torsoGeo = sphereGeo;
230: 
231:     const torso = new THREE.Mesh(sphereGeo, this.bodyMat);
232:     torso.scale.set(bodyW, bodyH, bodyLen);
233:     torso.position.y = bodyY;
234:     torso.castShadow = true;
235:     torso.receiveShadow = true;
236:     this.model.add(torso);
237:     this.torso = torso;
238: 
239:     const chest = new THREE.Mesh(sphereGeo, this.bodyMat);
240:     chest.scale.set(bodyW * 0.93, bodyH * 0.9, bodyLen * 0.56);
241:     chest.position.set(0, bodyY + 0.015, bodyLen * 0.58);
242:     chest.castShadow = true;
243:     this.model.add(chest);
244: 
245:     const hip = new THREE.Mesh(sphereGeo, this.bodyMat);
246:     hip.scale.set(bodyW * 0.86, bodyH * 0.84, bodyLen * 0.5);
247:     hip.position.set(0, bodyY + 0.005, -bodyLen * 0.58);
248:     hip.castShadow = true;
249:     this.model.add(hip);
250: 
251:     const belly = new THREE.Mesh(sphereGeo, this.bellyMat);
252:     belly.scale.set(bodyW * 0.8, bodyH * 0.42, bodyLen * 0.86);
253:     belly.position.set(0, bodyY - bodyH * 0.38, bodyLen * 0.06);
254:     this.model.add(belly);
255: 
256:     this.buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor });
257:     this.buildTail({ bodyLen, bodyH, bodyY, tailLen });
258:     this.buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen });
259:     this.buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen });
260:     this.buildAccents({ bodyLen, bodyW, bodyH, bodyY });
261:   }
262: 
263:   buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor }) {
264:     const g = this.genome;
265:     const neckGroup = new THREE.Group();
266:     neckGroup.position.set(0, bodyY + bodyH * 0.3, bodyLen * 0.69);
267:     neckGroup.rotation.x = 0.62 + g.neck * 0.2;
268:     this.model.add(neckGroup);
269:     this.neckGroup = neckGroup;
270: 
271:     const segCount = 4;
272:     for (let i = 0; i < segCount; i += 1) {
273:       const t = (i + 0.5) / segCount;
274:       const taper = 1 - t * 0.22;
275:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
276:       const segLen = neckLen / segCount;
277:       segment.scale.set(
278:         (0.14 + g.neck * 0.022) * taper,
279:         segLen * 0.68,
280:         (0.135 + g.neck * 0.02) * taper,
281:       );
282:       segment.position.set(0, t * neckLen, Math.sin(t * Math.PI) * 0.035);
283:       segment.castShadow = true;
284:       neckGroup.add(segment);
285:     }
286: 
287:     const headGroup = new THREE.Group();
288:     headGroup.position.set(0, neckLen + 0.045, 0.085);
289:     headGroup.rotation.x = -0.54;
290:     neckGroup.add(headGroup);
291:     this.headGroup = headGroup;
292: 
293:     const headR = 0.205 + g.crest * 0.026;
294:     const cranium = new THREE.Mesh(this.torsoGeo, this.bodyMat);
295:     cranium.scale.set(headR * 1.02, headR * 0.9, headR * 1.28);
296:     cranium.castShadow = true;
297:     headGroup.add(cranium);
298: 
299:     const snout = new THREE.Mesh(this.torsoGeo, this.bodyMat);
300:     snout.scale.set(headR * 0.72, headR * 0.5, headR * 1.05);
301:     snout.position.set(0, -headR * 0.17, headR * 1.48);
302:     snout.castShadow = true;
303:     headGroup.add(snout);
304: 
305:     const jaw = new THREE.Mesh(this.torsoGeo, this.bellyMat);
306:     jaw.scale.set(headR * 0.62, headR * 0.24, headR * 0.88);
307:     jaw.position.set(0, -headR * 0.55, headR * 1.36);
308:     headGroup.add(jaw);
309: 
310:     const browRidge = new THREE.Mesh(this.torsoGeo, this.limbMat);
311:     browRidge.scale.set(headR * 0.84, headR * 0.18, headR * 0.52);
312:     browRidge.position.set(0, headR * 0.5, headR * 0.36);
313:     headGroup.add(browRidge);
314: 
315:     for (const side of [-1, 1]) {
316:       const eyeSocket = new THREE.Mesh(this.torsoGeo, this.bellyMat);
317:       eyeSocket.scale.set(headR * 0.35, headR * 0.3, headR * 0.32);
318:       eyeSocket.position.set(side * headR * 0.78, headR * 0.25, headR * 0.62);
319:       headGroup.add(eyeSocket);
320: 
321:       const eye = new THREE.Mesh(this.torsoGeo, this.eyeMat);
322:       eye.scale.setScalar(headR * 0.22);
323:       eye.position.set(side * headR * 0.89, headR * 0.28, headR * 0.72);
324:       eye.userData.baseScaleY = headR * 0.22;
325:       headGroup.add(eye);
326:       this.eyes.push(eye);
327: 
328:       const glint = new THREE.Mesh(new THREE.SphereGeometry(1, 7, 5), this.glintMat);
329:       glint.scale.setScalar(headR * 0.055);
330:       glint.position.set(side * headR * 0.94, headR * 0.34, headR * 0.86);
331:       headGroup.add(glint);
332: 
333:       if (g.armor > 0.42) {
334:         const brow = new THREE.Mesh(new THREE.ConeGeometry(headR * 0.14, headR * (0.26 + g.armor * 0.4), 4), this.boneMat);
335:         brow.position.set(side * headR * 0.74, headR * 0.58, headR * 0.46);
336:         brow.rotation.set(-0.4, 0, side * -0.4);
337:         brow.castShadow = true;
338:         headGroup.add(brow);
339:       }
340:     }
341: 
342:     const nostrilGeo = new THREE.SphereGeometry(headR * 0.05, 6, 4);
343:     for (const side of [-1, 1]) {
344:       const nostril = new THREE.Mesh(nostrilGeo, this.eyeMat);
345:       nostril.position.set(side * headR * 0.18, -headR * 0.02, headR * 1.86);
346:       headGroup.add(nostril);
347:     }
348: 
349:     if (g.crest > 0.18) {
350:       const crest = new THREE.Mesh(makeCrestGeometry(), this.crestMat);
351:       crest.scale.set(0.46 + g.crest * 0.55, 0.32 + g.crest * 0.5, 1);
352:       crest.position.set(0, headR * 0.28, -headR * 0.12);
353:       crest.rotation.set(0.18, Math.PI / 2, 0.02);
354:       crest.castShadow = true;
355:       headGroup.add(crest);
356:       this.crestMeshes.push(crest);
357: 
358:       const crestBrother = crest.clone();
359:       crestBrother.position.x = 0.008;
360:       headGroup.add(crestBrother);
361:     }
362: 
363:     // Neck frill when display alleles are strong.
364:     if (g.crest > 0.64) {
365:       for (const side of [-1, 1]) {
366:         const frill = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.16, 4), this.accentMat);
367:         frill.position.set(side * 0.095, neckLen * 0.72, 0);
368:         frill.rotation.z = side * 1.15;
369:         neckGroup.add(frill);
370:       }
371:     }
372:   }
373: 
374:   buildTail({ bodyLen, bodyH, bodyY, tailLen }) {
375:     const g = this.genome;
376:     const base = new THREE.Group();
377:     base.position.set(0, bodyY + 0.01, -bodyLen * 0.77);
378:     base.rotation.x = -0.13;
379:     this.model.add(base);
380:     this.tailJoints.push(base);
381: 
382:     let parent = base;
383:     const segments = 5;
384:     const segLen = tailLen / segments;
385:     for (let i = 0; i < segments; i += 1) {
386:       const joint = new THREE.Group();
387:       joint.position.z = i === 0 ? 0 : -segLen;
388:       joint.rotation.x = i === 0 ? 0 : 0.035;
389:       parent.add(joint);
390:       const taper = 1 - (i / segments) * 0.82;
391:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
392:       segment.scale.set(0.115 * taper, 0.105 * taper, segLen * 0.72);
393:       segment.position.z = -segLen * 0.5;
394:       segment.castShadow = true;
395:       joint.add(segment);
396:       this.tailJoints.push(joint);
397:       parent = joint;
398:     }
399: 
400:     if (g.armor > 0.58) {
401:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
402:       club.position.z = -segLen * 0.92;
403:       club.scale.set(1.2, 0.85, 1.35);
404:       club.rotation.set(0.2, 0.4, 0.1);
405:       club.castShadow = true;
406:       parent.add(club);
407:     }
408:   }
409: 
410:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
411:     const g = this.genome;
412:     const upperLen = legLen * 0.55;
413:     const lowerLen = legLen * 0.48;
414:     const legRadius = 0.058 + g.bodySize * 0.032;
415:     const positions = [
416:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
417:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
418:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
419:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
420:     ];
421: 
422:     positions.forEach((entry, i) => {
423:       const root = new THREE.Group();
424:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
425:       this.model.add(root);
426: 
427:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
428:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
429:       root.add(shoulder);
430: 
431:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
432:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
433:       thigh.position.y = -upperLen * 0.36;
434:       thigh.castShadow = true;
435:       root.add(thigh);
436: 
437:       const upper = new THREE.Mesh(
438:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
439:         this.limbMat,
440:       );
441:       upper.position.y = -upperLen / 2;
442:       upper.castShadow = true;
443:       root.add(upper);
444: 
445:       const knee = new THREE.Group();
446:       knee.position.y = -upperLen;
447:       root.add(knee);
448: 
449:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
450:       kneeJoint.scale.setScalar(legRadius * 0.8);
451:       knee.add(kneeJoint);
452: 
453:       const lower = new THREE.Mesh(
454:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
455:         this.limbMat,
456:       );
457:       lower.position.y = -lowerLen / 2;
458:       lower.castShadow = true;
459:       knee.add(lower);
460: 
461:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
462:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
463:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
464:       foot.castShadow = true;
465:       knee.add(foot);
466: 
467:       for (let toe = -1; toe <= 1; toe += 1) {
468:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
469:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
470:         claw.rotation.x = Math.PI / 2.4;
471:         knee.add(claw);
472:       }
473: 
474:       this.legs.push({
475:         root,
476:         knee,
477:         phase: entry.phase,
478:         front: entry.front,
479:         upperLen,
480:         lowerLen,
481:         baseRot: entry.front ? 0.05 : -0.04,
482:       });
483:     });
484:   }
485: 
486:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
487:     const g = this.genome;
488:     if (g.armor < 0.22) return;
489:     const count = 3 + Math.round(g.armor * 5);
490:     for (let i = 0; i < count; i += 1) {
491:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
492:       const z = t * bodyLen * 0.76;
493:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
494:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
495:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
496:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
497:       spike.rotation.x = -0.34 - g.armor * 0.18;
498:       spike.rotation.y = Math.PI / 4;
499:       spike.castShadow = true;
500:       this.model.add(spike);
501:     }
502: 
503:     if (g.armor > 0.62) {
504:       for (const side of [-1, 1]) {
505:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
506:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
507:         plate.rotation.z = side * 0.6;
508:         plate.rotation.x = -0.3;
509:         plate.castShadow = true;
510:         this.model.add(plate);
511:       }
512:     }
513:   }
514: 
515:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
516:     const g = this.genome;
517:     const spotCount = Math.round(1 + g.pattern * 5);
518:     for (let i = 0; i < spotCount; i += 1) {
519:       const side = i % 2 === 0 ? -1 : 1;
520:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
521:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
522:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
523:       this.model.add(spot);
524:     }
525:   }
526: 
527:   buildCell() {
528:     const g = this.genome;
529:     this.sizeScale = 0.72 + g.bodySize * 0.3;
530:     this.dimensions = { bodyY: 0.1, neckLen: 0 };
531:     this.movementSpeed = 0;
532: 
533:     const cell = new THREE.Group();
534:     this.cellBody = new THREE.Mesh(new THREE.SphereGeometry(0.74, 32, 24), this.bodyMat);
535:     this.cellBody.scale.set(1, 0.9, 1);
536:     this.cellBody.castShadow = true;
537:     this.cellBody.receiveShadow = true;
538:     cell.add(this.cellBody);
539: 
540:     const membrane = new THREE.Mesh(
541:       new THREE.SphereGeometry(0.78, 32, 24),
542:       new THREE.MeshPhysicalMaterial({
543:         color: this.themeColor,
544:         transparent: true,
545:         opacity: 0.19,
546:         roughness: 0.22,
547:         metalness: 0.02,
548:         transmission: 0.18,
549:         thickness: 0.18,
550:         side: THREE.DoubleSide,
551:       }),
